"""Show (or save) a grid of faces generated by a trained generator."""
import argparse

import matplotlib.pyplot as plt
import numpy as np

from data import image_grid, to_uint8
from models import LATENT_DIM, load_generator


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--model", default="trained_generator.keras")
    parser.add_argument("--rows", type=int, default=6)
    parser.add_argument("--cols", type=int, default=4)
    parser.add_argument("--save", help="save the grid to this file instead of showing it")
    parser.add_argument("--bgr", action="store_true",
                        help="the model outputs BGR images (generators trained by the old OpenCV-based script)")
    args = parser.parse_args()

    generator = load_generator(args.model)
    z = np.random.normal(size=(args.rows * args.cols, LATENT_DIM)).astype(np.float32)
    images = to_uint8(generator.predict(z, verbose=0))
    if args.bgr:
        images = images[..., ::-1]
    grid = image_grid(images, args.rows, args.cols)

    if args.save:
        plt.imsave(args.save, grid)
    else:
        plt.imshow(grid)
        plt.axis("off")
        plt.show()


if __name__ == "__main__":
    main()
